{"file_text": "@namespace sv_9c530740ac7a48e7acb755be84843086.Components.Pages.Settings
@using sv_9c530740ac7a48e7acb755be84843086.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="form-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <span class="preview-label">Theme:</span> @_theme |
                <span class="preview-label">Font:</span> @_fontSize |
                <span class="preview-label">Lang:</span> @_language |
                <span class="preview-label">Compact:</span> @(_compactMode ? "Yes" : "No")
            </div>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _showSuccess;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
