arguments.file_text:
@page "/settings"
@using sv_9c530740ac7a48e7acb755be84843086.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

/* Settings Dashboard Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    font-weight: 500;
    color: #495057;
    border-left: 3px solid transparent;
    transition: all 0.2s;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #212529;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.15);
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: white;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast.success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background: #d1e7dd;
    color: #0f5132;
    border-radius: 0.375rem;
    border: 1px solid #badbcc;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-url {
    font-size: 0.85rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggle Labels */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
}

.panel-toggle {
    width: 100%;
    text-align: left;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* TFA Section */
.tfa-section {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
}

.status-indicator {
    margin-left: 0.5rem;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

.hint {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #6c757d;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.625rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

.sessions-table th {
    font-weight: 600;
    color: #495057;
    background: #f8f9fa;
}

.current-badge {
    font-size: 0.8rem;
    color: #0f5132;
    background: #d1e7dd;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin-top: 0;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 2px dashed #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.3s;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-card {
    font-size: 0.85rem;
    color: #6c757d;
}

.preview-label {
    font-weight: 600;
}

/* Preview theme variants */
.preview-theme-dark {
    background: #212529;
    color: #f8f9fa;
    border-color: #495057;
}

.preview-theme-dark .preview-card {
    color: #adb5bd;
}

.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-system {
    background: #f0f4f8;
    color: #212529;
    border-color: #a0b4c8;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-text {
    margin-bottom: 0.375rem;
}

/* Error message */
.error-message {
    color: #dc3545;
    font-size: 0.875rem;
    margin-bottom: 0.75rem;
}

